import { PROVIDER_ACTION } from './actions'

export const INITIAL_STATE = {}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case PROVIDER_ACTION.GET_USER_LIST:
    case PROVIDER_ACTION.GET_PROVIDER_LIST:
    case PROVIDER_ACTION.GET_PROVIDER_DETAIL:
    case PROVIDER_ACTION.GET_USER_DETAIL:
    case PROVIDER_ACTION.GET_BRANCH_LIST:
    case PROVIDER_ACTION.GET_INCOMING_COMMISSION_CONFIG_LIST:
    case PROVIDER_ACTION.ADD_INCOMING_COMMISSION_CONFIG:
    case PROVIDER_ACTION.UPDATE_INCOMING_COMMISSION_CONFIG:
    case PROVIDER_ACTION.GET_PRODUCT_LIST:
    case PROVIDER_ACTION.ADD_PROVIDER:
    case PROVIDER_ACTION.ADD_USER:
    case PROVIDER_ACTION.ADD_BRANCH:
    case PROVIDER_ACTION.GET_INDEPENDENT_PACKAGE_LIST:
    case PROVIDER_ACTION.GET_QUOTATION_DETAIL_LIST:
    case PROVIDER_ACTION.ADD_QUOTATION_DETAIL:
      return {
        ...state,
        ...payload
      }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer
