import { Col, Input, Row } from 'antd'
import { useEffect, useState, useCallback } from 'react'
import { loadDynamicScript } from '../../../../../helpers/loadDynamicScript'
import { GOOGLE_API_URL } from '../../constants'
import { LocationPickerStyle } from './index.style'
import PropTypes from 'prop-types'
import { debounce } from '../../../../../helpers/utility'
import isVNPath from '../../../../../helpers/isVNPath'

function LocationPicker (props) {
  const { onLatLngChange, latLng } = props
  const [isShowMap, setIsShowMap] = useState(false)

  const handleLatLngChange = useCallback((latLng, showMap = true) => {
    if (showMap) {
      setIsShowMap(true)
    }
    onLatLngChange(latLng)
  }, [onLatLngChange])

  const handleListners = useCallback(() => {
    const google = window.google
    const input = document.getElementById('searchTextField')
    const locationSearch = new google.maps.places.Autocomplete(input, {
      componentRestrictions: { country: isVNPath() ? ['vn'] : ['id'] },
      fields: ['address_components', 'geometry', 'icon', 'name']
    })
    google.maps.event.addListener(locationSearch, 'place_changed', debounce(() => {
      const place = locationSearch.getPlace()
      const lat = place.geometry.location.lat()
      const lng = place.geometry.location.lng()
      handleLatLngChange({ lat, lng })
      const map = new google.maps.Map(document.getElementById('map'), {
        center: { lat, lng },
        zoom: 15
      })
      const marker = new google.maps.Marker({
        position: { lat, lng },
        map,
        draggable: true
      })
      google.maps.event.addListener(marker, 'drag', function (event) {
        handleLatLngChange({
          lat: event.latLng.lat(),
          lng: event.latLng.lng()
        })
      })
    }, 200))
  }, [handleLatLngChange])

  useEffect(() => {
    if (!window.google) {
      loadDynamicScript(
        GOOGLE_API_URL,
        'gplaces',
        '',
        handleListners
      )
    } else {
      handleListners()
    }
  }, [handleListners])

  return (
    <LocationPickerStyle>
      <input id='searchTextField' type='text' size='50' />
      <div id='map' className={`${isShowMap ? '' : 'hide'}`} />
      <Row className='mt-15' type='flex' justify='space-between'>
        <Col span={11}>
          <p> Longitude </p>
          <Input
            type='text'
            placeholder='Longitude'
            onChange={(e) => {
              handleLatLngChange({
                ...latLng,
                lng: e.target.value
              }, false)
            }}
            value={latLng.lng}
          />
        </Col>
        <Col span={11}>
          <p> Latitude </p>
          <Input
            type='text'
            placeholder='Latitude'
            onChange={(e) => {
              handleLatLngChange({
                ...latLng,
                lat: e.target.value
              }, false)
            }}
            value={latLng.lat}
          />
        </Col>
      </Row>
    </LocationPickerStyle>
  )
}

LocationPicker.propTypes = {
  onLatLngChange: PropTypes.func,
  latLng: PropTypes.object
}

export default LocationPicker
