import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useProviderContextValue } from '../../context'
import { getProviderList, addProvider, getUserList, addUser, getBranchList, addBranch, getProviderDetail, getUserDetail, getIncomingCommissionConfigList, getProductList, addIncomingCommissionConfig, updateIncomingCommissionConfig, getIndependentPackageList, getQuotationDetailList, addQuotationDetail, updateQuotationDetail } from '../actions'

export const useProviderServiceCall = (actionsCall = () => {}) => {
  const [providerState, dispatch] = useProviderContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const request = useCallback(async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }, [callApi, actionsCall])

  return [providerState, request]
}

export const useGetUserList = () => useProviderServiceCall(getUserList)
export const useGetBranchList = () => useProviderServiceCall(getBranchList)
export const useGetProviderList = () => useProviderServiceCall(getProviderList)
export const useGetProviderDetail = () => useProviderServiceCall(getProviderDetail)
export const useGetUserDetail = () => useProviderServiceCall(getUserDetail)
export const useGetIncomingCommissionConfigList = () => useProviderServiceCall(getIncomingCommissionConfigList)
export const useAddIncomingCommissionConfig = () => useProviderServiceCall(addIncomingCommissionConfig)
export const useUpdateIncomingCommissionConfig = () => useProviderServiceCall(updateIncomingCommissionConfig)
export const useIndependentPackageList = () => useProviderServiceCall(getIndependentPackageList)
export const useGetProductList = () => useProviderServiceCall(getProductList)
export const useAddProvider = () => useProviderServiceCall(addProvider)
export const useAddUser = () => useProviderServiceCall(addUser)
export const useAddBranch = () => useProviderServiceCall(addBranch)
export const useGetQuotationDetailList = () => useProviderServiceCall(getQuotationDetailList)
export const useAddQuotationDetail = () => useProviderServiceCall(addQuotationDetail)
export const useUpdateQuotationDetail = () => useProviderServiceCall(updateQuotationDetail)
