/* eslint-disable react-hooks/exhaustive-deps */
import { useCallback, useEffect, useRef, useState } from 'react'
import { useGet, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { AutoComplete, Form, Input, Row, Col, Button } from 'antd'
import CircularLoader from '../../../../../../components/CircularLoader'
import { InputNumberStyle } from './index.style'
import { isVNPath } from '../../../../../../helpers/utility'
import { addressApiConfig } from '../apiConfig'
import { getCitiesListApi, getZipCodesListApi } from '../../../config/urls'

function AddressChangesContainer ({ form, onSave, address = {}, onCancel = () => {}, onGetSubmitMethod, fullWidth = false }) {
  const [isProvinceChange, setIsProvinceChange] = useState(false)
  const [getCityData = [], getCitiesRequest] = useGet(addressApiConfig.getCitiesList)
  const [getProvinceData = [], getProvinceRequest] = useGet(addressApiConfig.getProvincesList)
  const [getZipcodeData = [], getZipCodesRequest] = useGet(addressApiConfig.getZipCodesList)

  const that = useRef({
    ...address
  })

  const [{ GET_CITY_LOADER, GET_PROVINCE_LOADER, GET_ZIPCODE_LOADER }] = useLoaderContextValue()
  const formItemRef = useRef({
    labelCol: { span: 6 },
    wrapperCol: { span: 14 }
  })

  useEffect(() => {
    getProvinceRequest()
    if (address.province_code) {
      if (isVNPath()) {
        getZipCodesRequest({}, {
          url: getZipCodesListApi(address.province_code)
        })
      } else {
        getCitiesRequest({}, {
          url: getCitiesListApi(address.province_code)
        })
      }
    }
  }, [])

  const getFormFieldsDecorator = useCallback(({ name, title, error, defaultValue }, renderElement) => {
    const formItemProps = {
      label: title
    }
    if (fullWidth) {
      formItemProps.labelCol = { span: 24 }
      formItemProps.wrapperCol = { span: 24 }
    }
    return (
      <Form.Item {...formItemProps}>
        {
          form.getFieldDecorator(
            name,
            {
              rules: [
                {
                  required: true,
                  message: error || `Please enter ${title}`
                }
              ],
              initialValue: defaultValue
            }
          )(renderElement)
        }
      </Form.Item>
    )
  }, [form.getFieldDecorator])

  const handleSearchSelect = useCallback((text, option, type) => {
    // handle search the text
    if (type === 'province') {
      that.current = {
        ...that.current,
        ...getProvinceData[option.props.index]
      }
      form.resetFields(['city_code', 'postal_code'])
      setIsProvinceChange(true)
      if (isVNPath()) {
        getZipCodesRequest({}, {
          url: getZipCodesListApi(text)
        })
      } else {
        getCitiesRequest({}, {
          url: getCitiesListApi(text)
        })
      }
    } else {
      if (isVNPath()) {
        that.current = {
          ...that.current,
          ...getZipcodeData[option.props.index]
        }
      } else {
        that.current = {
          ...that.current,
          ...getCityData[option.props.index]
        }
      }
    }
  }, [getCitiesRequest, getZipCodesRequest, getProvinceData, getCityData, getZipcodeData, form])

  const handleSubmit = useCallback(async () => {
    return (
      new Promise((resolve, reject) => {
        form.validateFields((err, values) => {
          if (err) {
            resolve({})
          } else {
            resolve({
              ...that.current,
              ...values
            })
          }
        })
      })
    )
  }, [])

  const handleSave = useCallback(() => {
    form.validateFields((err, values) => {
      if (err) {
        return
      }
      if (onSave) {
        onSave({
          ...that.current,
          ...values
        })
      } else {
        return {
          ...that.current,
          ...values
        }
      }
    })
  }, [onSave])

  useEffect(() => {
    if (onGetSubmitMethod) {
      onGetSubmitMethod(handleSubmit)
    }
  }, [])

  const renderAgentList = (list, key, displayKey) => {
    return list.map((listItem, index) => (
      <AutoComplete.Option key={listItem[key]} value={listItem[key]} index={index}>
        {listItem[displayKey]}
      </AutoComplete.Option>
    ))
  }

  return (
    <CircularLoader isSpining={GET_CITY_LOADER || GET_PROVINCE_LOADER || GET_ZIPCODE_LOADER}>
      <Form {...formItemRef.current} noValidate>
        {
          getFormFieldsDecorator(
            {
              name: 'province_code',
              title: 'Select Province',
              error: 'Please select the Province!',
              defaultValue: isProvinceChange ? '' : address?.province_code
            },
            (
              <AutoComplete
                dataSource={(
                  renderAgentList(getProvinceData, 'province_code', 'province_name')
                )}
                onSelect={(value, data) => handleSearchSelect(value, data, 'province')}
                filterOption={(inputValue, option) => (
                  option.props.children.toUpperCase().indexOf(inputValue.toUpperCase()) !== -1
                )}
                placeholder='Please select the province'
              />
            )
          )
        }
        {
          isVNPath()
            ? (
                getFormFieldsDecorator(
                  {
                    name: 'postal_code',
                    title: 'Select Zip Code',
                    error: 'Please select the zip code!',
                    defaultValue: isProvinceChange ? '' : address?.postal_code
                  },
                  (
                    <AutoComplete
                      dataSource={(
                        renderAgentList(getZipcodeData, 'zipcode', 'zipcode')
                      )}
                      filterOption={(inputValue, option) => (
                        option.props.children.indexOf(inputValue) !== -1
                      )}
                      onSelect={(value, data) => handleSearchSelect(value, data, 'zipcode')}
                      placeholder='Please enter the Zip Code'
                    />
                  )
                ))
            : (
              <>
                {
                  getFormFieldsDecorator(
                    {
                      name: 'city_code',
                      title: 'Select City',
                      error: 'Please select the city!',
                      defaultValue: isProvinceChange ? '' : address?.city_code
                    },
                    (
                      <AutoComplete
                        dataSource={(
                          renderAgentList(getCityData, 'city_code', 'city_name')
                        )}
                        filterOption={(inputValue, option) => (
                          option.props.children.toUpperCase().indexOf(inputValue.toUpperCase()) !== -1
                        )}
                        onSelect={(value, data) => handleSearchSelect(value, data, 'city')}
                        placeholder='Please enter the city'
                      />
                    )
                  )
                }
                {
                  getFormFieldsDecorator(
                    {
                      name: 'postal_code',
                      title: 'Postal Code',
                      error: 'Please Enter the Postal Code!',
                      defaultValue: address?.postal_code
                    },
                    (
                      <InputNumberStyle
                        type='number'
                        placeholder='Please enter the postal code'
                      />
                    )
                  )
                }
              </>)
        }
        {
          getFormFieldsDecorator(
            {
              name: 'address',
              title: 'Address',
              error: 'Please Enter the address',
              defaultValue: address?.address
            },
            (
              <Input.TextArea
                type='text'
                placeholder='Please enter the address'
              />
            )
          )
        }
        {
          !onGetSubmitMethod &&
            <Row type='flex' justify='end' align='center'>
              <Col xl={5} md={5}>
                <Button onClick={onCancel}>Cancel</Button>
              </Col>
              <Col>
                <Button type='primary' onClick={handleSave}>Save</Button>
              </Col>
            </Row>
        }
      </Form>
    </CircularLoader>
  )
}

export default Form.create()(AddressChangesContainer)
