export const getProviderDetail = (payload) => ({
  type: PROVIDER_ACTION.GET_PROVIDER_DETAIL_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: getAgentProviderApi(payload.providerCode)
  }
})

