import React from 'react'
import { Button, Col, Icon, Row } from 'antd'
import PermissionCheckerV2 from '../../../../../components/permissionCheckerV2'
import FilterInput from '../../../../../components/tables/components/FilterInput'
import { COLORS } from '../../../../../constants/colors'
import Cookies from 'universal-cookie'
import moment from 'moment-timezone'

const cookies = new Cookies()

export function providerListTable ({
  handleProviderDetailPage,
  searchTextQuery,
  handleInputChange,
  handleSearch,
  isFilterVisible,
  setIsFilterVisible,
  isChange
}) {
  return [
    {
      key: 'provider_action',
      title: 'Action',
      dataIndex: 'provider_id',
      render: (val, record) => (
        <PermissionCheckerV2 requiredPermission='ops.view_agent_provider_list'>
          <i className='far fa-eye agent-config-btn' onClick={() => handleProviderDetailPage(record.code)} />
        </PermissionCheckerV2>
      ),
      align: 'center'
    },
    {
      key: 'provider_name',
      title: 'Name',
      dataIndex: 'name',
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: searchTextQuery.name && COLORS.blue
          }}
        />
      ),
      filterDropdown: (
        <FilterInput
          idIdentifier='name'
          className='agent-table-search'
          searchText={isChange ? searchTextQuery.name : ''}
          onInputChange={e => handleInputChange(e, 'name')}
          onSearch={e => handleSearch(e, 'name')}
        />
      ),
      filterDropdownVisible: isFilterVisible === 'name',
      onFilterDropdownVisibleChange: (visible) => setIsFilterVisible(visible ? 'name' : searchTextQuery.name)
    },
    {
      key: 'provider_code',
      title: 'Code',
      dataIndex: 'code',
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: searchTextQuery.code && '#1890ff'
          }}
        />
      ),
      filterDropdown: (
        <FilterInput
          idIdentifier='agent_code_id'
          className='agent-table-search'
          searchText={isChange ? searchTextQuery.code : ''}
          onInputChange={e => handleInputChange(e, 'code')}
          onSearch={e => handleSearch(e, 'code')}
        />
      ),
      filterDropdownVisible: isFilterVisible === 'code',
      onFilterDropdownVisibleChange: (visible) => setIsFilterVisible(visible ? 'code' : searchTextQuery.code)
    },
    {
      key: 'provider_email',
      title: 'Email',
      dataIndex: 'email',
      align: 'center'
    },
    {
      key: 'provider_contact_number',
      title: 'Phone No (Claims)',
      dataIndex: 'headquarter_branch.claims_contact_no',
      align: 'center'
    },
    {
      key: 'provider_claims_email',
      title: 'Email (claims)',
      dataIndex: 'headquarter_branch.claims_email',
      align: 'center'
    },
    {
      key: 'provider_created_at',
      title: 'Created At',
      dataIndex: 'created_at',
      align: 'center',
      render: (val, record) => {
        const userTimeZone = cookies.get('userProfile').user_timezone
        return moment(val).tz(userTimeZone).format('MMM DD,YYYY hh:mm A')
      }
    }
  ]
}

