import { resetError, useErrorContextValue } from '@pasarpolis/common-react-hooks'
import { Button, Form, Row } from 'antd'
import { isEmpty } from 'lodash'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import renderFormItemsUtil from '../../../../../../helpers/renderFormItems'
import { showNotification } from '../../../../../../components/ShowNotification'
import AddressChanges from '../../../components/AddressChanges'
import UploadImgPreview from '../../../components/UploadImgPreview'
import { useAddProvider } from '../../state/hooks/useProviderState'
import { ProviderFormStyle } from './index.style'
import LocationPicker from '../../../components/LocationPicker'
import get from 'lodash/get'
import PropTypes from 'prop-types'

function ProviderForm (props) {
  const { defaultValues } = props
  const addressSubmit = useRef('')
  const [logoImg, setLogoImg] = useState(get(defaultValues, 'logo_url', ''))
  const [latLng, setLatLng] = useState({
    lat: get(defaultValues, 'headquarter_branch.location.latitude', ''),
    lng: get(defaultValues, 'headquarter_branch.location.longitude', '')
  })
  const [autoCancel, setAutoCancel] = useState(get(defaultValues, 'cancellation_details.enable_auto_cancel', false))
  const [logoUrlError, setLogoUrlError] = useState('')
  const handleLatLngChange = useCallback((newLatLng) => {
    setLatLng(newLatLng)
  }, [])

  const [, addProviderRequest] = useAddProvider()

  const [{ ADD_PROVIDER_ERROR, addProviderStatus },
    dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    if (addProviderStatus === 'success') {
      if (defaultValues) {
        showNotification('success', 'Provider successfully Edited')
      } else {
        showNotification('success', 'A new provider is successfully added')
      }

      dispatchError(resetError({
        addProviderStatus: ''
      }))
      if (defaultValues) {
        props.onGetProviderDetail({
          providerCode: defaultValues?.code
        })
      } else {
        props.onFetchProviderList({})
      }
      props.onCloseProviderForm()
    } else if (ADD_PROVIDER_ERROR && addProviderStatus) {
      showNotification('error', addProviderStatus)
      dispatchError(resetError({
        addProviderStatus: ''
      }))
    }
  }, [addProviderStatus, defaultValues, dispatchError,
    ADD_PROVIDER_ERROR, props
  ])

  const handleSubmit = useCallback((e) => {
    e.preventDefault()
    if (!logoImg) {
      setLogoUrlError('Please Upload Logo!')
    }
    props.form.validateFields(async (err, values) => {
      if (!err) {
        const addrData = await addressSubmit.current()
        if (!isEmpty(addrData)) {
          const finalData = {
            headquarter_branch: {
              location: {
                ...addrData,
                latitude: latLng.lat ? latLng.lat : null,
                longitude: latLng.lng ? latLng.lng : null
              },
              claims_email: values.claims_email,
              claims_contact_no: values.claims_contact_no
            },
            code: values.code,
            name: values.name,
            logo_url: logoImg,
            email: values.email,
            cancellation_details: {
              enable_auto_cancel: values.enable_auto_cancel,
              ...(values.enable_auto_cancel ? { provider_ppw_days: values.provider_ppw_days || 0 } : { provider_ppw_days: 60 })
            }
          }
          addProviderRequest({
            providerCode: defaultValues?.code,
            body: finalData
          })
        }
      }
    })
  }, [latLng, logoImg, addProviderRequest,
    defaultValues, props.form
  ])

  const renderFormItems = useCallback((item) => {
    // wrapping utitily function with class function to pass common parameters
    return renderFormItemsUtil({
      ...item,
      getFieldDecorator: props.form.getFieldDecorator,
      getFieldValue: props.form.getFieldValue
    })
  }, [props.form])

  const renderForm = useCallback((formData) => {
    return (
      formData.map((item, index) => (
        renderFormItems(item)
      ))
    )
  }, [renderFormItems])

  const handleGetSubmitMethods = useCallback((method) => {
    addressSubmit.current = method
  }, [])

  const handleSaveNewUploadImg = useCallback((file) => {
    setLogoUrlError('')
    setLogoImg(file)
  }, [])

  const handleRemoveImg = useCallback(() => {
    setLogoImg('')
  }, [])

  const defaultAddr = useMemo(() => {
    let addr = get(defaultValues, 'headquarter_branch.location', {})
    if (addr === null) {
      addr = {}
    }
    return addr
  }, [defaultValues])

  return (
    <ProviderFormStyle>
      <Form onSubmit={handleSubmit}>
        {
          renderForm([
            {
              name: 'name',
              title: 'Provider Name',
              subTitle: 'name',
              type: 'text',
              defaultValue: get(defaultValues, 'name', ''),
              max: 80,
              min: 3
            },
            {
              name: 'code',
              title: 'Provider Code',
              type: 'text',
              defaultValue: get(defaultValues, 'code', ''),
              max: 30
            },
            {
              name: 'email',
              title: 'Email',
              subTitle: 'email',
              type: 'email',
              defaultValue: get(defaultValues, 'email', ''),
              required: false,
              max: 240
            }
          ])
        }
        <p>
          Upload Logo
        </p>
        <div className='errorText'>{logoUrlError}</div>

        <UploadImgPreview
          onSave={(file) => handleSaveNewUploadImg(file)}
          name='provider_logo'
          img={logoImg}
          isNew={!logoImg}
          fileType='.png,.jpg,.jpeg'
          onRemove={handleRemoveImg}
        />
        <AddressChanges
          address={defaultAddr}
          onGetSubmitMethod={handleGetSubmitMethods}
          fullWidth
        />
        {
          renderForm([
            {
              name: 'claims_contact_no',
              title: 'Contact Number for Claims',
              subTitle: 'claims_contact_no',
              type: 'number',
              defaultValue: get(defaultValues, 'headquarter_branch.claims_contact_no', ''),
              required: false,
              max: 14
            },
            {
              name: 'claims_email',
              title: 'Email for Claims',
              subTitle: 'claims_email',
              type: 'email',
              defaultValue: get(defaultValues, 'headquarter_branch.claims_email', ''),
              required: false,
              max: 240
            }
          ])
        }
        {
          renderForm([
            {
              name: 'enable_auto_cancel',
              radioDataKey: 'enable_auto_cancel',
              title: 'Auto Cancel Outstanding Payment',
              subTitle: 'enable_auto_cancel',
              type: 'hybrid_radio',
              defaultValue: autoCancel,
              isKeyDisabled: () => true,
              isEnableType: true,
              onlyRadio: true,
              runtimeRequestParams: {},
              handleRuntimeParams: (data) => {
                setAutoCancel(() => (data.value))
              },
              data: [
                {
                  value: true,
                  title: 'Yes'
                },
                {
                  value: false,
                  title: 'No'
                }
              ]
            }
          ])
        }
        {
          autoCancel &&
          renderForm([
            {
              name: 'provider_ppw_days',
              title: 'Payment Period (days)',
              subTitle: 'provider_ppw_days',
              type: 'number',
              max: 999,
              min: 0,
              defaultValue: get(defaultValues, 'cancellation_details.provider_ppw_days', 60),
              required: true
            }
          ])
        }
        <p className='label'> Select Location: </p>
        <LocationPicker latLng={latLng} onLatLngChange={handleLatLngChange} />
        <Row justify='end' type='flex'>
          <Button className='mt-20' type='primary' htmlType='submit'>
            Submit
          </Button>
        </Row>
      </Form>
    </ProviderFormStyle>
  )
}

ProviderForm.propTypes = {
  defaultValues: PropTypes.object,
  onGetProviderDetail: PropTypes.func,
  onFetchProviderList: PropTypes.func,
  onCloseProviderForm: PropTypes.func
}

const wrapperProviderForm = Form.create()(ProviderForm)

export default wrapperProviderForm
